  "language": "Solidity",
  "sources": {
    "src/PerpEngine.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {IActionHandler} from "./interface/IActionHandler.sol";
import {IPerpEngine} from "./interface/IPerpEngine.sol";
import {IPythLazer} from "./interface/IPythLazer.sol";
import {LiquidationSharedLib} from "./lib/LiquidationSharedLib.sol";
import {RealizePnlLib} from "./lib/RealizePnlLib.sol";
import {Account} from "./lib/storage/Account.sol";
import {Exchange} from "./lib/storage/Exchange.sol";
import {FeeCollector} from "./lib/storage/FeeCollector.sol";
import {Liquidator} from "./lib/storage/Liquidator.sol";
import {PerpPosition} from "./lib/storage/PerpPosition.sol";
import {PerpProduct} from "./lib/storage/PerpProduct.sol";
import {Token} from "./lib/storage/Token.sol";
import {WORST_CASE_REALIZED_PNL_ERROR} from "./share/Constants.sol";
import {DecimalMath} from "./share/DecimalMath.sol";
import {ActionType, EngineType, OrderSide, ProductStatus} from "./share/Enums.sol";
import {
    DelistAlreadyInitiated,
    DelistMessageIdxMismatch,
    DelistNotInitiated,
    DelistNotInvoked,
    DelistOpenInterestRemaining,
    ExcludedAccount,
    InvalidFillNotional,
    InvalidFillQuantity,
    InvalidMatchZeroQuantity,
    InvalidNonIncreasingId,
    InvalidNonce,
    InvalidOrderPrice,
    InvalidOrderPriceNotCrossed,
    InvalidOrderProduct,
    InvalidOrderQuantity,
    InvalidOrderSameSide,
    InvalidOrderZeroPrice,
    InvalidParameter,
    InvalidPositionFeeLiquidatorCredit,
    InvalidRealizedPnl,
    InvalidReduceOnlyFill,
    InvalidReduceOnlyFillQuantity,
    InvalidSigner,
    P_ERR_AMT_GT_MAX,
    P_ERR_AMT_ZERO,
    P_ERR_BAD_ADDR,
    P_ERR_BAD_VAL,
    P_ERR_FOUND,
    P_ERR_NOT_FOUND,
    PendingPerpProductUpdateMismatch,
    PendingPerpProductUpdateNotFound,
    PositionFeeLiquidatorNotConfigured,
    PositionNotFound,
    ProductIdMismatch,
    ProductNotFound,
    ProductStatusViolation,
    RealizeFundingProductQuoteTokenMismatch,
    RealizeFundingProductsMismatch,
    SubaccountNotFound,
    ZeroAddress,
    ZeroMessageIdx
} from "./share/Errors.sol";
import {ActionId} from "./share/UserDefinedTypes.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {FixedPointMathLib as Math} from "solady/utils/FixedPointMathLib.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";

contract PerpEngine is IPerpEngine {
    using SafeCastLib for int128;
    using SafeCastLib for int256;
    using SafeCastLib for uint128;
    using SafeCastLib for uint256;
    using DecimalMath for int128;
    using DecimalMath for int256;
    using DecimalMath for uint128;
    using DecimalMath for uint256;
    using Account for Account.Data;
    using Account for Account.DataGlobal;
    using Exchange for Exchange.Data;
    using PerpPosition for PerpPosition.Data;
    using FeeCollector for FeeCollector.Data;
    using EnumerableSet for EnumerableSet.AddressSet;
    using EnumerableSet for EnumerableSet.Bytes32Set;

    /// @dev Tolerance for fill notional verification.
    uint16 private constant FILL_NOTIONAL_TOLERANCE = 13;

    /// @inheritdoc IPerpEngine
    function finalizeUpdate(ActionId id, IActionHandler.FinalizePerpProductUpdateAction calldata action)
        external
        payable
    {
        PerpProduct.Data storage product = PerpProduct.load(action.productId);
        if (product.id == 0) {
            revert ProductNotFound(id, action.productId, EngineType.PERP);
        }

        if (action.messageIdx == 0) {
            revert ZeroMessageIdx(id);
        }

        IPerpEngine.UpdatePerpProductParams storage pending = PerpProduct.loadPendingUpdate(action.productId);
        if (pending.id == 0) {
            revert PendingPerpProductUpdateNotFound(id, action.productId);
        }

        if (
            action.maxLeverage != pending.maxLeverage || action.maxOpenInterestUsd != pending.maxOpenInterestUsd
                || action.maxPositionNotionalUsd != pending.maxPositionNotionalUsd
                || action.maxQuantity != pending.maxQuantity
        ) {
            revert PendingPerpProductUpdateMismatch(id, action.productId);
        }

        delete pending.id;
        delete pending.maxLeverage;
        delete pending.maxQuantity;
        delete pending.maxOpenInterestUsd;
        delete pending.maxPositionNotionalUsd;

        product.maxLeverage = action.maxLeverage;
        product.maxOpenInterestUsd = action.maxOpenInterestUsd;
        product.maxPositionNotionalUsd = action.maxPositionNotionalUsd;
        product.maxQuantity = action.maxQuantity;

        emit PerpProductUpdated(action.productId);
        emit PerpProductUpdateFinalized(action.productId, action.messageIdx);
    }

    function initiateDelist(ActionId id, IActionHandler.InitiatePerpProductDelistAction calldata action)
        external
        payable
    {
        PerpProduct.Data storage product = PerpProduct.load(action.productId);
        if (product.id == 0) {
            revert ProductNotFound(id, action.productId, EngineType.PERP);
        }
        if (product.status != ProductStatus.ACTIVE) {
            revert ProductStatusViolation(id, action.productId, EngineType.PERP, product.status);
        }
        if (!product.delistInvoked) {
            revert DelistNotInvoked(id, action.productId);
        }
        if (product.delistMessageIdx != 0) {
            revert DelistAlreadyInitiated(id, action.productId, product.delistMessageIdx);
        }
        if (action.messageIdx == 0) {
            revert ZeroMessageIdx(id);
        }

        Exchange.Data storage exchange = Exchange.load();
        (bytes memory payload,) =
            IPythLazer(exchange.pythLazer).verifyUpdate{value: action.pythFee}(action.pythPriceUpdate);
        uint128 expiryPrice =
            LiquidationSharedLib.parsePythPriceFeed(id, payload, product.pythFeedId, exchange.pythMaxAge);

        product.delistMessageIdx = action.messageIdx;
        product.delistExpiryPrice = expiryPrice;

        emit PerpProductDelistInitiated(action.productId, expiryPrice, action.messageIdx);
    }

    /// @inheritdoc IPerpEngine
    function finalizeDelist(ActionId id, IActionHandler.FinalizePerpProductDelistAction calldata action)
        external
        payable
    {
        PerpProduct.Data storage product = PerpProduct.load(action.productId);
        if (product.id == 0) {
            revert ProductNotFound(id, action.productId, EngineType.PERP);
        }
        if (product.status != ProductStatus.ACTIVE) {
            revert ProductStatusViolation(id, action.productId, EngineType.PERP, product.status);
        }
        if (!product.delistInvoked) {
            revert DelistNotInvoked(id, action.productId);
        }
        if (product.delistMessageIdx == 0) {
            revert DelistNotInitiated(id, action.productId);
        }
        if (action.messageIdx != product.delistMessageIdx) {
            revert DelistMessageIdxMismatch(id, action.productId, action.messageIdx, product.delistMessageIdx);
        }

        uint128 openInterest = product.openInterest;
        if (openInterest != 0) {
            revert DelistOpenInterestRemaining(id, action.productId, openInterest);
        }

        product.status = ProductStatus.DELISTED;

        emit PerpProductDelistFinalized(action.productId, product.delistExpiryPrice, action.messageIdx);
    }

    /// @inheritdoc IPerpEngine
    function settleDelistPosition(ActionId id, IActionHandler.PerpProductDelistPositionSettlementAction calldata action)
        external
        payable
    {
        PerpProduct.Data storage product = PerpProduct.load(action.productId);
        if (product.id == 0) {
            revert ProductNotFound(id, action.productId, EngineType.PERP);
        }

        ProductStatus status = product.status;
        if (status != ProductStatus.ACTIVE) {
            revert ProductStatusViolation(id, action.productId, EngineType.PERP, status);
        }
        if (!product.delistInvoked) {
            revert DelistNotInvoked(id, action.productId);
        }
        if (product.delistMessageIdx == 0) {
            revert DelistNotInitiated(id, action.productId);
        }
        if (action.messageIdx != product.delistMessageIdx) {
            revert DelistMessageIdxMismatch(id, action.productId, action.messageIdx, product.delistMessageIdx);
        }

        PerpPosition.Data storage position = product.positions[action.account][action.subaccount];
        int128 size = position.size;
        if (size == 0) {
            revert PositionNotFound(id, action.account, action.subaccount, action.productId);
        }

        uint128 closeNotional = Math.abs(size).mulDecimal(product.delistExpiryPrice).toUint128();
        int128 cRealizedPnl = (closeNotional.toInt128() - position.cost.toInt128()) * size.getSign();
        _verifyRealizedPnl(id, action.realizedPnl, cRealizedPnl, WORST_CASE_REALIZED_PNL_ERROR);

        _settleDelistPositionBalance(product, position, action, size);

        if (size > 0) {
            product.openInterest -= uint128(size);
        }

        position.clear();

        emit PerpProductDelistPositionSettlement(
            action.account, action.subaccount, action.productId, size, action.realizedPnl, action.messageIdx
        );
    }

    function _settleDelistPositionBalance(
        PerpProduct.Data storage product,
        PerpPosition.Data storage position,
        IActionHandler.PerpProductDelistPositionSettlementAction calldata action,
        int128 size
    ) private {
        address quoteTokenAddress = Token.load(product.quoteTokenName).tokenAddress;
        Account.Data storage accountData = Account.load(action.account);
        int256 realizedFunding =
            product.cumulativeFundingUsd.mulDecimal(size) - position.lastFundingUsd.mulDecimal(size);
        uint128 absSize = Math.abs(size).toUint128();
        uint256 realizedPositionFee =
            product.cumulativePositionFeeUsd.mulDecimal(absSize) - position.lastPositionFeeUsd.mulDecimal(absSize);

        // If this delist settlement loss would make the cross-margin cash balance negative, the
        // matching engine must emit RealizePnl actions for profitable non-delisted positions
        // before this action. By this point, any such compensation is already reflected in
        // `accountData.balance`.
        accountData.balance[action.subaccount][quoteTokenAddress] = (accountData.balance[action.subaccount][quoteTokenAddress].toInt256()
                + action.realizedPnl - realizedFunding - realizedPositionFee.toInt256())
        .toUint256();
        accountData.openPositionsByQuoteToken[action.subaccount][quoteTokenAddress] -= 1;
        accountData.openPositions[action.subaccount] -= 1;
    }

    /// @inheritdoc IPerpEngine
    function executeMatch(
        ActionId id,
        IActionHandler.MatchOrdersAction calldata action,
        ExecuteMatchDigests calldata digests
    ) external payable {
        (Account.Data storage makerAccount, Account.Data storage takerAccount) = _executeMatch(id, action, digests);
        emit PerpOrderMatched(
            action.maker.productId,
            makerAccount.sender,
            takerAccount.sender,
            action.maker.subaccount,
            action.taker.subaccount,
            action.maker.side,
            action.taker.side,
            action.fillQuantity,
            action.maker.price,
            action.makerFee,
            action.takerFee,
            action.messageIdx
        );
    }

    /// @inheritdoc IPerpEngine
    function updateFunding(ActionId id, uint32 productId, int128 fundingDeltaUsd, uint64 messageIdx) external payable {
        PerpProduct.Data storage product = PerpProduct.load(productId);
        if (product.id == 0) {
            revert ProductNotFound(id, productId, EngineType.PERP);
        }

        if (product.status != ProductStatus.ACTIVE) {
            revert ProductStatusViolation(id, productId, EngineType.PERP, product.status);
        }

        int128 cumulativeFundingUsd = product.cumulativeFundingUsd + fundingDeltaUsd;
        product.cumulativeFundingUsd = cumulativeFundingUsd;
        emit PerpProductFundingUpdated(productId, fundingDeltaUsd, cumulativeFundingUsd, messageIdx);
    }

    /// @inheritdoc IPerpEngine
    function updatePositionFee(
        ActionId id,
        uint32 productId,
        uint128 positionFeeDeltaUsd,
        uint256 eLiquidatorCreditAmount,
        uint64 messageIdx
    ) external payable {
        PerpProduct.Data storage product = PerpProduct.load(productId);
        if (product.id == 0) {
            revert ProductNotFound(id, productId, EngineType.PERP);
        }

        if (product.status != ProductStatus.ACTIVE) {
            revert ProductStatusViolation(id, productId, EngineType.PERP, product.status);
        }

        Liquidator.Data memory liquidator = Liquidator.load();
        if (liquidator.account == address(0) || liquidator.subaccount == bytes32(0)) {
            revert PositionFeeLiquidatorNotConfigured(id);
        }
        uint256 cLiquidatorCreditAmount = positionFeeDeltaUsd.mulDecimal(product.openInterest * 2);
        int256 liquidatorCreditAmountDiff = eLiquidatorCreditAmount.toInt256() - cLiquidatorCreditAmount.toInt256();
        if (Math.abs(liquidatorCreditAmountDiff) > WORST_CASE_REALIZED_PNL_ERROR) {
            revert InvalidPositionFeeLiquidatorCredit(id, eLiquidatorCreditAmount, cLiquidatorCreditAmount);
        }

        uint128 cumulativePositionFeeUsd = product.cumulativePositionFeeUsd + positionFeeDeltaUsd;
        product.cumulativePositionFeeUsd = cumulativePositionFeeUsd;

        address quoteToken = Token.load(product.quoteTokenName).tokenAddress;
        Account.load(liquidator.account).balance[liquidator.subaccount][quoteToken] += eLiquidatorCreditAmount;

        emit PerpProductPositionFeeUpdated(
            productId, positionFeeDeltaUsd, cumulativePositionFeeUsd, eLiquidatorCreditAmount, messageIdx
        );
    }

    /// @inheritdoc IPerpEngine
    function realizeFunding(
        ActionId id,
        address account,
        bytes32 subaccount,
        uint32[] calldata productIds,
        uint64 messageIdx
    ) external payable {
        Account.Data storage accountData = Account.load(account);

        _verifyAccountOrLiquidator(id, account, subaccount, accountData);

        // No-op when there are no products to realize rather than reverting.
        if (productIds.length == 0) {
            return;
        }

        // Number of open positions (by product) does not match the requesting number of products.
        bytes32 quoteTokenName = PerpProduct.load(productIds[0]).quoteTokenName;
        address quoteToken = Token.load(quoteTokenName).tokenAddress;

        // Funding should only be realized within its own margin pool and never cross-margin in the same action.
        if (accountData.openPositionsByQuoteToken[subaccount][quoteToken] != productIds.length) {
            revert RealizeFundingProductsMismatch(
                id,
                account,
                subaccount,
                accountData.openPositionsByQuoteToken[subaccount][quoteToken],
                uint128(productIds.length)
            );
        }

        int256 realizedFundingUsd = 0;
        uint32 lastProcessedProductId = 0;

        for (uint256 i = 0; i < productIds.length; i++) {
            PerpProduct.Data storage product = PerpProduct.load(productIds[i]);
            uint32 productId = product.id;

            if (productId != productIds[i]) {
                revert ProductIdMismatch(id, productIds[i], productId);
            }

            if (product.id == 0) {
                revert ProductNotFound(id, productIds[i], EngineType.PERP);
            }

            // A sorted productIds array ensures no duplicate products were specified.
            if (productId <= lastProcessedProductId) {
                revert InvalidNonIncreasingId(id, productId, lastProcessedProductId);
            }
            lastProcessedProductId = productId;

            if (product.quoteTokenName != quoteTokenName) {
                revert RealizeFundingProductQuoteTokenMismatch(id, productIds[i], product.quoteTokenName);
            }

            PerpPosition.Data storage position = product.positions[account][subaccount];
            int128 positionSize = position.size;
            // This implicitly checks that the product is also delisted because OI would be zero and
            // there are no remaining positions opened and hence this will fail.
            if (positionSize == 0) {
                revert PositionNotFound(id, account, subaccount, productId);
            }

            // Apply funding charged between the `lastFundingUsd` and current product cumFundingUsd.
            int128 cumulativeFundingUsd = product.cumulativeFundingUsd;
            realizedFundingUsd += int256(
                cumulativeFundingUsd.mulDecimal(positionSize) - position.lastFundingUsd.mulDecimal(positionSize)
            );
            position.lastFundingUsd = cumulativeFundingUsd;
        }

        // No-op and emit even if realizedFundingUsd is zero (positions touched within last hr or funding is net zero).
        accountData.balance[subaccount][quoteToken] =
            (accountData.balance[subaccount][quoteToken].toInt256() - realizedFundingUsd).toUint256();
        emit PerpFundingRealized(account, subaccount, productIds, realizedFundingUsd, messageIdx);
    }

    /// @inheritdoc IPerpEngine
    function realizePnl(
        ActionId id,
        address account,
        bytes32 subaccount,
        uint32 productId,
        int128 costDelta,
        uint64 messageIdx
    ) external payable {
        Account.Data storage accountData = Account.load(account);

        _verifyAccountOrLiquidator(id, account, subaccount, accountData);

        PerpProduct.Data storage product = PerpProduct.load(productId);
        if (product.id == 0) {
            revert ProductNotFound(id, productId, EngineType.PERP);
        }
        if (product.status != ProductStatus.ACTIVE) {
            revert ProductStatusViolation(id, productId, EngineType.PERP, product.status);
        }

        PerpPosition.Data storage position = product.positions[account][subaccount];
        uint128 absCostDelta = RealizePnlLib.applyRealizePnl(id, account, subaccount, productId, position, costDelta);

        address quoteToken = Token.load(product.quoteTokenName).tokenAddress;
        accountData.balance[subaccount][quoteToken] += absCostDelta;
        emit PerpPnlRealized(account, subaccount, productId, costDelta, messageIdx);
    }

    // --- Helpers --- //

    /// @dev Verifies the account exists and subaccount is registered, unless the account is the configured liquidator.
    function _verifyAccountOrLiquidator(
        ActionId id,
        address account,
        bytes32 subaccount,
        Account.Data storage accountData
    ) private view {
        Liquidator.Data memory liquidator = Liquidator.load();
        if (account == liquidator.account && subaccount == liquidator.subaccount) {
            return;
        }

        if (accountData.sender != account) {
            revert SubaccountNotFound(id, account, subaccount);
        }
        if (!accountData.isSubaccountRegistered(subaccount)) {
            revert SubaccountNotFound(id, account, subaccount);
        }
    }

    /// @dev Validates basic match requirements and returns the product.
    function _verifyMatch(
        ActionId id,
        IActionHandler.TradeOrder calldata makerOrder,
        IActionHandler.TradeOrder calldata takerOrder
    ) private view returns (PerpProduct.Data storage product) {
        product = PerpProduct.load(makerOrder.productId);

        // Product does not exist.
        if (product.id == 0) {
            revert ProductNotFound(id, makerOrder.productId, EngineType.PERP);
        }
        if (product.status != ProductStatus.ACTIVE) {
            revert ProductStatusViolation(id, makerOrder.productId, EngineType.PERP, product.status);
        }
        // Maker and taker must be on different sides i.e. BUY vs. SELL.
        if (makerOrder.side == takerOrder.side) {
            revert InvalidOrderSameSide(id, makerOrder.side);
        }
        // Maker and taker must deal with same product
        if (makerOrder.productId != takerOrder.productId) {
            revert InvalidOrderProduct(id, makerOrder.productId, takerOrder.productId);
        }
    }

    /// @dev Reverts if the product or order require that a fill reduces the position size.
    function _verifyNotReduceOnly(
        ActionId id,
        IActionHandler.TradeOrder calldata order,
        int128 oldSize,
        int128 sizeDelta
    ) private pure {
        if (order.reduceOnly) {
            revert InvalidReduceOnlyFill(id, oldSize, sizeDelta);
        }
    }

    /// @dev Validates the price of the maker and taker orders and returns the trade price.
    function _verifyPrice(
        ActionId id,
        IActionHandler.TradeOrder calldata makerOrder,
        IActionHandler.TradeOrder calldata takerOrder
    ) private pure returns (uint128 price) {
        // The order prices must cross if the taker is a limit order.
        price = makerOrder.price;
        bool isMarketOrder = takerOrder.price == 0;
        if (!isMarketOrder) {
            if (
                (makerOrder.side == OrderSide.BUY && price < takerOrder.price)
                    || (makerOrder.side == OrderSide.SELL && price > takerOrder.price)
            ) {
                revert InvalidOrderPriceNotCrossed(id, price, takerOrder.price);
            }
        }
    }

    /// @dev Reverts if order validations do not pass. However assumes signatures have been verified upstream.
    function _verifyOrder(
        PerpProduct.Data storage product,
        IActionHandler.TradeOrder memory order,
        bool isTaker,
        ActionId id
    ) internal view returns (Account.Data storage) {
        // Zero price is a market order. Only taker market orders are possible.
        if (!isTaker && order.price == 0) {
            revert InvalidOrderZeroPrice(id);
        }

        // Cannot exceed maximum qty, must be a multiple of lotSize, and zero qty orders only allowed for reduce-only.
        if (
            // Zero qty orders are valid for reduce-only (such as close orders).
            order.quantity > product.maxQuantity || order.quantity % product.lotSize != 0
                || (order.quantity == 0 && !order.reduceOnly)
        ) {
            revert InvalidOrderQuantity(id, order.quantity);
        }

        // If a price exists then it must be a multiple of tickSize.
        if (order.price != 0 && order.price % product.tickSize != 0) {
            revert InvalidOrderPrice(id, order.price);
        }

        Account.DataGlobal storage accountGlobal = Account.load();
        Account.Data storage account = accountGlobal.resolveAccount(order.sender);
        address resolvedSender = account.sender;

        if (accountGlobal.excludedAccounts[resolvedSender]) {
            revert ExcludedAccount(id, resolvedSender);
        }

        if (!account.isSubaccountRegistered(order.subaccount)) {
            revert SubaccountNotFound(id, order.sender, order.subaccount);
        }

        // Check if the signer is associated to named subaccount
        if ((resolvedSender != order.sender) && !account.linkedSigners[order.subaccount].contains(order.sender)) {
            revert InvalidSigner(id, order.sender);
        }

        if (account.isNonceUsed(order.sender, ActionType.MatchOrders, order.nonce)) {
            revert InvalidNonce(id, order.nonce);
        }

        return account;
    }

    /// @dev Checks that realized pnl (from the sequencer/matching engine) is within tolerance of the internally calculated reference value.
    function _verifyRealizedPnl(ActionId id, int128 externalValue, int128 internalValue, uint128 tolerance) private {
        uint256 absDiff = Math.abs(externalValue - internalValue);
        if (absDiff > tolerance) {
            revert InvalidRealizedPnl(id, externalValue, internalValue, tolerance);
        }
    }

    /// @dev Checks that the fill notional (from the sequencer/matching engine) is within tolerance of the internally calculated reference value.
    function _verifyFillNotional(ActionId id, uint128 externalValue, uint128 internalValue) private {
        uint256 absDiff = Math.abs(externalValue.toInt128() - internalValue.toInt128());
        uint256 tolerance = (uint256(internalValue) >> 52) + FILL_NOTIONAL_TOLERANCE;
        if (absDiff > tolerance) {
            revert InvalidFillNotional(id, externalValue, internalValue, tolerance.toUint128());
        } else if (absDiff > 0) {
            emit PerpFillNotionalMismatch(id, externalValue, internalValue, tolerance.toUint128());
        }
    }

    /// @dev Charges fee against maker/taker and credits to fee collector if gt zero.
    function _chargeFee(
        address quoteToken,
        uint128 makerFee,
        uint128 takerFee,
        Account.Data storage makerAccount,
        Account.Data storage takerAccount,
        bytes32 makerSubaccount,
        bytes32 takerSubaccount,
        uint64 messageIdx
    ) private {
        uint256 collectedFee = uint256(makerFee) + takerFee;
        if (collectedFee > 0) {
            if (makerFee > 0) {
                makerAccount.balance[makerSubaccount][quoteToken] -= makerFee;
            }
            if (takerFee > 0) {
                takerAccount.balance[takerSubaccount][quoteToken] -= takerFee;
            }

            FeeCollector.load().accrueFees(quoteToken, collectedFee, messageIdx);
        }
    }

    /// @dev Validates realized pnl, updates the account position and balance.
    function _settlePosition(
        ActionId id,
        PerpPosition.Data storage cPosition,
        Account.Data storage account,
        address quoteToken,
        IActionHandler.TradeOrder calldata order,
        IPerpEngine.FillData memory cFillData,
        int128 cumulativeFundingUsd,
        uint128 cumulativePositionFeeUsd,
        IPerpEngine.ExternalFillData memory eFillData
    ) internal returns (uint128 cNewPositionCost) {
        if (cFillData.oldSize == 0) {
            // OPEN new position:
            // - `eRealizedPnl` must be zero
            _verifyNotReduceOnly(id, order, cFillData.oldSize, cFillData.sizeDelta);
            _verifyRealizedPnl(id, eFillData.eRealizedPnl, 0, 0);
            cNewPositionCost = eFillData.eFillNotional;
            account.openPositions[order.subaccount] += 1;
            account.openPositionsByQuoteToken[order.subaccount][quoteToken] += 1;
        } else if (cFillData.newSize == 0) {
            // CLOSE existing position completely and realize PnL:
            // - `eRealizedPnl` must align with with `eFillNotional - cPosition.cost` within tolerance
            _verifyRealizedPnl(
                id,
                eFillData.eRealizedPnl,
                (eFillData.eFillNotional.toInt128() - cPosition.cost.toInt128()) * cFillData.oldSize.getSign(),
                WORST_CASE_REALIZED_PNL_ERROR
            );
            account.openPositions[order.subaccount] -= 1;
            account.openPositionsByQuoteToken[order.subaccount][quoteToken] -= 1;
        } else if (cFillData.oldSize > 0 != cFillData.newSize > 0) {
            // CHANGE_SIDE/FLIP position side (long to short or short to long) and realize closed portion's pnl:
            // - `cCloseNotional` may differ from the external counterpart within realized PnL tolerance.
            // - `eRealizedPnl` must align with `cCloseNotional - cOldCost`.
            uint128 cOldCost = cPosition.cost;
            uint128 cCloseNotional = Math.abs(cFillData.oldSize).mulDecimal(cFillData.price).toUint128();
            int8 oldSideSign = cFillData.oldSize.getSign();
            _verifyNotReduceOnly(id, order, cFillData.oldSize, cFillData.sizeDelta);
            _verifyRealizedPnl(
                id,
                eFillData.eRealizedPnl,
                (cCloseNotional.toInt128() - cOldCost.toInt128()) * oldSideSign,
                WORST_CASE_REALIZED_PNL_ERROR
            );
            cNewPositionCost = (eFillData.eFillNotional.toInt128() - (eFillData.eRealizedPnl * oldSideSign)
                        - cOldCost.toInt128()).toUint256().toUint128();
        } else if (cFillData.oldSize > 0 == cFillData.sizeDelta > 0) {
            // INCREASE position in the same direction:
            // - `eRealizedPnl` must be zero
            _verifyNotReduceOnly(id, order, cFillData.oldSize, cFillData.sizeDelta);
            _verifyRealizedPnl(id, eFillData.eRealizedPnl, 0, 0);
            cNewPositionCost = cPosition.cost + eFillData.eFillNotional;
        } else {
            // DECREASE/REDUCE position size (partial close) and realize closed portion's pnl:
            // - `cReduceCost` is inherently imprecise due to division
            // - `eRealizedPnl` must align with `eFillNotional - cReduceCost` within tolerance
            uint128 cOldCost = cPosition.cost;
            uint128 cReduceCost = Math.fullMulDiv(cFillData.quantity, cOldCost, Math.abs(cFillData.oldSize)).toUint128();
            int128 sideSign = cFillData.oldSize.getSign();
            _verifyRealizedPnl(
                id,
                eFillData.eRealizedPnl,
                (eFillData.eFillNotional.toInt128() - cReduceCost.toInt128()) * sideSign,
                WORST_CASE_REALIZED_PNL_ERROR
            );
            cNewPositionCost = (cOldCost.toInt128() - eFillData.eFillNotional.toInt128() + eFillData.eRealizedPnl
                        * sideSign).toUint256().toUint128();
        }

        int256 realizedFunding;
        uint256 realizedPositionFee;
        if (cFillData.oldSize != 0) {
            realizedFunding = cumulativeFundingUsd.mulDecimal(cFillData.oldSize)
                - cPosition.lastFundingUsd.mulDecimal(cFillData.oldSize);
            uint128 absSize = Math.abs(cFillData.oldSize).toUint128();
            realizedPositionFee =
                cumulativePositionFeeUsd.mulDecimal(absSize) - cPosition.lastPositionFeeUsd.mulDecimal(absSize);
        }

        int256 tokenBalance = account.balance[order.subaccount][quoteToken].toInt256();
        account.balance[order.subaccount][quoteToken] =
            (tokenBalance + eFillData.eRealizedPnl - realizedFunding - realizedPositionFee.toInt256()).toUint256();
    }

    /// @dev Settle the position updating size & cost, product oi and account balance.
    function _settlePositionFill(
        ActionId id,
        Account.Data storage account,
        PerpPosition.Data storage position,
        PerpProduct.Data storage product,
        address quoteToken,
        IActionHandler.TradeOrder calldata order,
        IPerpEngine.FillData memory fillData,
        IPerpEngine.ExternalFillData memory eFillData
    ) private {
        int128 cumulativeFundingUsd = product.cumulativeFundingUsd;
        uint128 cumulativePositionFeeUsd = product.cumulativePositionFeeUsd;
        fillData.oldSize = position.size;

        // Determine the new position size (neg = short, pos = long)
        bool isBuyOrder = order.side == OrderSide.BUY;
        fillData.sizeDelta = (isBuyOrder ? fillData.quantity.toInt256() : -fillData.quantity.toInt256()).toInt128();
        fillData.newSize = fillData.oldSize + fillData.sizeDelta;

        // Calculate funding settlement and PnL for open positions.
        uint128 newCost = _settlePosition(
            id,
            position,
            account,
            quoteToken,
            order,
            fillData,
            cumulativeFundingUsd,
            cumulativePositionFeeUsd,
            eFillData
        );

        // Why oldSize > 0 when calculating OI?
        //
        // Only look at long positions when calc open interest to avoid doubling up. If this order modifies a short
        // or results in a short, the other will handle the update on the other side. Additionally, we update open
        // interest twice as the position may be flipped from long to short or short to long.
        //
        // (1) Remove the position size from OI if long
        // (2) Add the new position size back if remain long
        uint128 openInterest = product.openInterest;
        if (fillData.oldSize > 0) {
            openInterest -= uint128(fillData.oldSize);
        }
        if (fillData.newSize > 0) {
            openInterest += uint128(fillData.newSize);
        }
        product.openInterest = openInterest;

        // Update position.
        if (fillData.newSize == 0) {
            position.clear();
        } else {
            position.update(
                PerpPosition.Data({
                    size: fillData.newSize,
                    cost: newCost,
                    lastFundingUsd: cumulativeFundingUsd,
                    lastPositionFeeUsd: cumulativePositionFeeUsd
                })
            );
        }
    }

    /// @dev Calculates the maximum fillable quantity available to an order, considering position size for reduce-only.
    function _calcFillableQuantity(
        PerpPosition.Data storage position,
        IActionHandler.TradeOrder calldata order,
        uint128 filledQuantity
    ) private view returns (uint128) {
        // For a standard order, whatever has not been filled of the quantity is still fillable.
        if (!order.reduceOnly) {
            return order.quantity - filledQuantity;
        }
        // If the quantity is zero (close order) the position quantity is the fillable quantity.
        uint128 positionQuantity = Math.abs(position.size).toUint128();
        if (order.quantity == 0) {
            return positionQuantity;
        }

        uint128 orderFillableQuantity = order.quantity - filledQuantity;
        return Math.min(positionQuantity, orderFillableQuantity).toUint128();
    }

    /// @dev Calculates and update the filled amounts for maker and taker orders.
    function _settleOrderFills(
        ActionId id,
        ExecuteMatchDigests calldata digests,
        IActionHandler.MatchOrdersAction calldata action,
        PerpProduct.Data storage product,
        PerpPosition.Data storage makerPosition,
        PerpPosition.Data storage takerPosition,
        Account.Data storage makerAccount,
        Account.Data storage takerAccount
    ) private returns (uint128 fillQuantity) {
        uint128 makerFillQty = product.filled[digests.maker];
        uint128 takerFillQty = product.filled[digests.taker];

        uint128 makerFillableQty = _calcFillableQuantity(makerPosition, action.maker, makerFillQty);
        uint128 takerFillableQty = _calcFillableQuantity(takerPosition, action.taker, takerFillQty);

        fillQuantity = Math.min(makerFillableQty, takerFillableQty).toUint128();

        // If the order is reduce-only, the order could have already been reduced by previous a size reduction.
        if (action.maker.reduceOnly || action.taker.reduceOnly) {
            if (action.fillQuantity > fillQuantity) {
                revert InvalidReduceOnlyFillQuantity(id, action.fillQuantity, fillQuantity);
            }
            fillQuantity = action.fillQuantity;
        }

        // Empty matches are invalid.
        if (fillQuantity == 0) {
            revert InvalidMatchZeroQuantity(id, makerFillableQty, takerFillableQty);
        }

        // If an order is fully filled, its fill quantity is removed and its nonce consumed.
        // Otherwise the fill quantity is updated.
        if (makerFillableQty == fillQuantity) {
            makerAccount.usedNonces[action.maker.sender][ActionType.MatchOrders][action.maker.nonce] = true;
            delete product.filled[digests.maker];
        } else {
            product.filled[digests.maker] = makerFillQty + fillQuantity;
        }
        if (takerFillableQty == fillQuantity) {
            takerAccount.usedNonces[action.taker.sender][ActionType.MatchOrders][action.taker.nonce] = true;
            delete product.filled[digests.taker];
        } else {
            product.filled[digests.taker] = takerFillQty + fillQuantity;
        }
    }

    /// @dev Performs a match of orders, settles position, and updates product details
    function _executeMatch(
        ActionId id,
        IActionHandler.MatchOrdersAction calldata action,
        ExecuteMatchDigests calldata digests
    ) private returns (Account.Data storage makerAccount, Account.Data storage takerAccount) {
        PerpProduct.Data storage product = _verifyMatch(id, action.maker, action.taker);

        address quoteToken = Token.load(product.quoteTokenName).tokenAddress;

        makerAccount = _verifyOrder(product, action.maker, false, id);
        takerAccount = _verifyOrder(product, action.taker, true, id);

        {
            IPerpEngine.FillData memory fillData;
            fillData.price = _verifyPrice(id, action.maker, action.taker);

            PerpPosition.Data storage makerPosition = product.positions[makerAccount.sender][action.maker.subaccount];
            PerpPosition.Data storage takerPosition = product.positions[takerAccount.sender][action.taker.subaccount];

            fillData.quantity = _settleOrderFills(
                id, digests, action, product, makerPosition, takerPosition, makerAccount, takerAccount
            );

            if (action.fillQuantity != fillData.quantity) {
                revert InvalidFillQuantity(id, action.fillQuantity, fillData.quantity);
            }

            _verifyFillNotional(id, action.fillNotional, fillData.quantity.mulDecimal(fillData.price).toUint128());

            // For self-trading we omit any position updates, skip funding and don't realize pnl as the trade always nets out
            if (makerAccount.sender != takerAccount.sender || action.maker.subaccount != action.taker.subaccount) {
                {
                    IPerpEngine.ExternalFillData memory eFillData;
                    eFillData.eFillNotional = action.fillNotional;
                    eFillData.eRealizedPnl = action.makerRealizedPnl;
                    _settlePositionFill(
                        id, makerAccount, makerPosition, product, quoteToken, action.maker, fillData, eFillData
                    );
                }
                {
                    IPerpEngine.ExternalFillData memory eFillData;
                    eFillData.eFillNotional = action.fillNotional;
                    eFillData.eRealizedPnl = action.takerRealizedPnl;
                    _settlePositionFill(
                        id, takerAccount, takerPosition, product, quoteToken, action.taker, fillData, eFillData
                    );
                }
            }
        }

        _chargeFee(
            quoteToken,
            action.makerFee,
            action.takerFee,
            makerAccount,
            takerAccount,
            action.maker.subaccount,
            action.taker.subaccount,
            action.messageIdx
        );
    }
}
