    "src/lib/LiquidationSharedLib.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {
    LiquidatorInsufficientBalance,
    PriceFeedInvalidProperty,
    PriceFeedMissingProperty,
    PriceFeedTimestampAfterPayload,
    PriceFeedsTooMany,
    PriceInvalidExponent,
    PriceInvalidFeedId,
    PriceNegative,
    PriceTooOld,
    PriceZero
} from "../share/Errors.sol";
import {ActionId} from "../share/UserDefinedTypes.sol";
import {PythLazerLib} from "./external/pyth/PythLazerLib.sol";
import {Account} from "./storage/Account.sol";
import {Liquidator} from "./storage/Liquidator.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";

library LiquidationSharedLib {
    using SafeCastLib for int256;
    using SafeCastLib for uint256;

    // Must match offchain supported range.
    int16 private constant MAX_EXPONENT = -1;
    int16 private constant MIN_EXPONENT = -8;

    uint64 private constant MICROSECONDS_PER_SECOND = 1_000_000;

    struct PriceData {
        uint64 timestamp;
        uint64 feedUpdateTimestamp;
        int64 price;
        int16 exponent;
        PythLazerLib.Channel channel;
        uint32 feedId;
    }

    /// @dev Returns the first price in the provided list of feeds.
    function parsePythPriceFeed(ActionId id, bytes memory payload, uint32 feedId, uint64 maxAge)
        internal
        view
        returns (uint128)
    {
        PriceData memory data;
        uint8 feedsLength;
        uint16 pos;

        (data.timestamp, data.channel, feedsLength, pos) = PythLazerLib.parsePayloadHeader(payload);

        if (feedsLength != 1) {
            revert PriceFeedsTooMany(id, feedsLength);
        }

        uint8 propertiesLength;
        (data.feedId, propertiesLength, pos) = PythLazerLib.parseFeedHeader(payload, pos);

        for (uint8 j = 0; j < propertiesLength; j++) {
            PythLazerLib.PriceFeedProperty property;
            (property, pos) = PythLazerLib.parseFeedProperty(payload, pos);

            if (property == PythLazerLib.PriceFeedProperty.Price) {
                (data.price, pos) = PythLazerLib.parseFeedValueInt64(payload, pos);
            } else if (property == PythLazerLib.PriceFeedProperty.Exponent) {
                (data.exponent, pos) = PythLazerLib.parseFeedValueInt16(payload, pos);
            } else if (property == PythLazerLib.PriceFeedProperty.BestBidPrice) {
                (, pos) = PythLazerLib.parseFeedValueInt64(payload, pos);
            } else if (property == PythLazerLib.PriceFeedProperty.BestAskPrice) {
                (, pos) = PythLazerLib.parseFeedValueInt64(payload, pos);
            } else if (property == PythLazerLib.PriceFeedProperty.PublisherCount) {
                (, pos) = PythLazerLib.parseFeedValueUint16(payload, pos);
            } else if (property == PythLazerLib.PriceFeedProperty.FeedUpdateTimestamp) {
                uint8 exists;
                (exists, pos) = PythLazerLib.parseFeedValueUint8(payload, pos);
                if (exists != 0) {
                    (data.feedUpdateTimestamp, pos) = PythLazerLib.parseFeedValueUint64(payload, pos);
                }
            } else {
                revert PriceFeedInvalidProperty(id, property);
            }
        }

        if (data.exponent < MIN_EXPONENT || data.exponent > MAX_EXPONENT) {
            revert PriceInvalidExponent(id, data.exponent);
        }
        uint16 exponent = uint16(9 + data.exponent);

        if (data.feedId != feedId) {
            revert PriceInvalidFeedId(id, data.feedId, feedId);
        }
        if (data.feedUpdateTimestamp == 0) {
            revert PriceFeedMissingProperty(id, PythLazerLib.PriceFeedProperty.FeedUpdateTimestamp);
        }
        if (data.feedUpdateTimestamp > data.timestamp) {
            revert PriceFeedTimestampAfterPayload(id, data.feedUpdateTimestamp, data.timestamp);
        }
        uint64 priceTimestamp = data.feedUpdateTimestamp / MICROSECONDS_PER_SECOND;
        if (priceTimestamp + maxAge < block.timestamp) {
            revert PriceTooOld(id, priceTimestamp, uint64(block.timestamp));
        }
        if (data.price < 0) {
            revert PriceNegative(id, data.price);
        }
        if (data.price == 0) {
            revert PriceZero(id);
        }

        return uint128(uint64(data.price)) * (10 ** exponent).toUint128();
    }

    /// @dev Updates the liquidator's balance and reverts on negative balance.
    function updateLiquidatorBalance(
        ActionId id,
        Account.Data storage liquidatorAccount,
        Liquidator.Data memory liquidator,
        address token,
        int256 delta
    ) internal {
        if (delta == 0) {
            return;
        }
        uint256 priorBalance = liquidatorAccount.balance[liquidator.subaccount][token];
        int256 newBalance = priorBalance.toInt256() + delta;
        if (newBalance < 0) {
            revert LiquidatorInsufficientBalance(
                id, liquidator.account, liquidator.subaccount, token, priorBalance, delta
            );
        }
        liquidatorAccount.balance[liquidator.subaccount][token] = newBalance.toUint256();
    }
}
"
    },
    "src/lib/RealizePnlLib.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {InvalidRealizePnlCostDelta, InvalidRealizePnlNegativeCost, PositionNotFound} from "../share/Errors.sol";
import {ActionId} from "../share/UserDefinedTypes.sol";
import {PerpPosition} from "./storage/PerpPosition.sol";
import {FixedPointMathLib as Math} from "solady/utils/FixedPointMathLib.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";

library RealizePnlLib {
    using SafeCastLib for uint128;

    /// @dev Applies pre-realized PnL cost updates to a position and returns the quote balance credit.
    ///      Valid cost deltas have the same sign as position size. The position cost changes by `costDelta`,
    ///      and callers credit `abs(costDelta)` to the quote balance.
    function applyRealizePnl(
        ActionId id,
        address account,
        bytes32 subaccount,
        uint32 productId,
        PerpPosition.Data storage position,
        int128 costDelta
    ) internal returns (uint128 absCostDelta) {
        int128 positionSize = position.size;

        if (positionSize == 0) {
            revert PositionNotFound(id, account, subaccount, productId);
        }

        if ((positionSize > 0 && costDelta <= 0) || (positionSize < 0 && costDelta >= 0)) {
            revert InvalidRealizePnlCostDelta(id, account, subaccount, productId, positionSize, costDelta);
        }

        int128 newCost = position.cost.toInt128() + costDelta;
        if (newCost < 0) {
            revert InvalidRealizePnlNegativeCost(id, account, subaccount, productId, position.cost, costDelta);
        }

        position.cost = uint128(newCost);
        absCostDelta = uint128(Math.abs(costDelta));
    }
}
"
    },
    "src/lib/external/pyth/PythLazerLib.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

// @see: https://github.com/pyth-network/pyth-crosschain/blob/main/lazer/contracts/evm/src/PythLazerLib.sol
//
// NOTE: Adjusted to use `bytes memory update` from `bytes calldata update`.
library PythLazerLib {
    enum PriceFeedProperty {
        Price,
        BestBidPrice,
        BestAskPrice,
        PublisherCount,
        Exponent,
        Confidence,
        FundingRate,
        FundingTimestamp,
        FundingRateInterval,
        MarketSession,
        EmaPrice,
        EmaConfidence,
        FeedUpdateTimestamp
    }

    enum Channel {
        Invalid,
        RealTime,
        FixedRate50,
        FixedRate200
    }

    function parsePayloadHeader(bytes memory update)
        internal
        pure
        returns (uint64 timestamp, Channel channel, uint8 feedsLen, uint16 pos)
    {
        uint32 FORMAT_MAGIC = 2479346549;

        pos = 0;
        // Manual byte concatenation for uint32/bytes4
        bytes4 magicBytes = bytes4(abi.encodePacked(update[pos], update[pos + 1], update[pos + 2], update[pos + 3]));
        uint32 magic = uint32(magicBytes);
        pos += 4;
        if (magic != FORMAT_MAGIC) {
            revert("invalid magic");
        }

        // Manual byte concatenation for uint64/bytes8
        bytes8 timestampBytes = bytes8(
            abi.encodePacked(
                update[pos],
                update[pos + 1],
                update[pos + 2],
                update[pos + 3],
                update[pos + 4],
                update[pos + 5],
                update[pos + 6],
                update[pos + 7]
            )
        );
        timestamp = uint64(timestampBytes);
        pos += 8;

        channel = Channel(uint8(update[pos]));
        pos += 1;
        feedsLen = uint8(update[pos]);
        pos += 1;
    }

    function parseFeedHeader(bytes memory update, uint16 pos)
        internal
        pure
        returns (uint32 feed_id, uint8 num_properties, uint16 new_pos)
    {
        // Manual byte concatenation for uint32/bytes4
        bytes4 feedIdBytes = bytes4(abi.encodePacked(update[pos], update[pos + 1], update[pos + 2], update[pos + 3]));
        feed_id = uint32(feedIdBytes);
        pos += 4;
        num_properties = uint8(update[pos]);
        pos += 1;
        new_pos = pos;
    }

    function parseFeedProperty(bytes memory update, uint16 pos)
        internal
        pure
        returns (PriceFeedProperty property, uint16 new_pos)
    {
        property = PriceFeedProperty(uint8(update[pos]));
        pos += 1;
        new_pos = pos;
    }

    function parseFeedValueUint64(bytes memory update, uint16 pos)
        internal
        pure
        returns (uint64 value, uint16 new_pos)
    {
        // Manual byte concatenation for uint64/bytes8
        bytes8 valueBytes = bytes8(
            abi.encodePacked(
                update[pos],
                update[pos + 1],
                update[pos + 2],
                update[pos + 3],
                update[pos + 4],
                update[pos + 5],
                update[pos + 6],
                update[pos + 7]
            )
        );
        value = uint64(valueBytes);
        pos += 8;
        new_pos = pos;
    }

    function parseFeedValueInt64(bytes memory update, uint16 pos) internal pure returns (int64 value, uint16 new_pos) {
        // Manual byte concatenation for int64/bytes8
        bytes8 valueBytes = bytes8(
            abi.encodePacked(
                update[pos],
                update[pos + 1],
                update[pos + 2],
                update[pos + 3],
                update[pos + 4],
                update[pos + 5],
                update[pos + 6],
                update[pos + 7]
            )
        );
        value = int64(uint64(valueBytes));
        pos += 8;
        new_pos = pos;
    }

    function parseFeedValueUint16(bytes memory update, uint16 pos)
        internal
        pure
        returns (uint16 value, uint16 new_pos)
    {
        // Manual byte concatenation for uint16/bytes2
        bytes2 valueBytes = bytes2(abi.encodePacked(update[pos], update[pos + 1]));
        value = uint16(valueBytes);
        pos += 2;
        new_pos = pos;
    }

    function parseFeedValueInt16(bytes memory update, uint16 pos) internal pure returns (int16 value, uint16 new_pos) {
        // Manual byte concatenation for int16/bytes2
        bytes2 valueBytes = bytes2(abi.encodePacked(update[pos], update[pos + 1]));
        value = int16(uint16(valueBytes));
        pos += 2;
        new_pos = pos;
    }

    function parseFeedValueUint8(bytes memory update, uint16 pos) internal pure returns (uint8 value, uint16 new_pos) {
        value = uint8(update[pos]);
        pos += 1;
        new_pos = pos;
    }
}
"
    },
    "src/lib/storage/Account.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {IActionHandler} from "../../interface/IActionHandler.sol";
import {ActionType} from "../../share/Enums.sol";
import {InvalidNonce, InvalidSigner, SignerNotFound, SubaccountNotFound} from "../../share/Errors.sol";
import {ActionId} from "../../share/UserDefinedTypes.sol";
import {Deposit} from "./Deposit.sol";
import {Withdraw} from "./Withdraw.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {SafeCastLib} from "solady/utils/SafeCastLib.sol";

library Account {
    using Account for Account.Data;
    using EnumerableSet for EnumerableSet.AddressSet;
    using SafeCastLib for uint128;
    using SafeCastLib for uint256;
    using SafeCastLib for int256;
    using SafeCastLib for int128;

    bytes32 constant _SLOT_PATH = keccak256(abi.encode("xyz.meridian.Account.Data"));

    // --- Storage --- //

    struct DataGlobal {
        /// Exchange settlement stablecoin address
        address usdToken;
        // Total backed balance across all concrete tokens, excludes virtual/synthetic tokens.
        mapping(address token => uint256 amount) totalBackedBalance;
        /// Total token deposit balance across all accounts
        mapping(address token => uint256 amount) totalBalance;
        /// Total pending token deposit balance across all accounts
        mapping(address token => uint256 amount) totalPendingBalance;
        /// Signer to the msg.sender (account) address (one-time linking)
        mapping(address signer => address account) linkedSignersToAccount;
        /// Whether a Signer has already been used or is excluded from being a Signer
        mapping(address signer => bool excluded) excludedSigners;
        /// Whether an Account is forbidden from trading related operations (trade, deposit, withdraw)
        mapping(address account => bool excluded) excludedAccounts;
    }

    struct Data {
        /// The account owner address
        address sender;
        /// Count of registered subaccounts after finalized deposit.
        uint32 registeredSubaccounts;
        /// Token deposit balance of account by subaccount
        mapping(bytes32 subaccount => mapping(address token => uint256 amount)) balance;
        /// Whether the subaccount has ever had a prior deposit
        mapping(bytes32 subaccount => bool hasDeposited) hasRegistered;
        /// Whether the nonce of the sender (account or signer) has been used (by actionType)
        mapping(address sender => mapping(ActionType => mapping(uint64 nonce => bool hasUsed))) usedNonces;
        /// Linked signer by subaccount approved for tx signing
        mapping(bytes32 subaccount => EnumerableSet.AddressSet linkedSigner) linkedSigners;
        /// Number of open positions by subaccount
        mapping(bytes32 subaccount => uint128 amount) openPositions;
        /// Number of open positions by subaccount and quote token
        mapping(bytes32 subaccount => mapping(address quoteToken => uint128 amount)) openPositionsByQuoteToken;
        /// Mapping of subaccount to a pending deposit
        mapping(bytes32 subaccount => Deposit.Data pendingDeposit) pendingDeposit;
        /// Mapping of the withdraw digest to a pending withdraw
        mapping(bytes32 digest => Withdraw.Data pendingWithdraw) pendingWithdraw;
        /// @dev Mapping of pending signer revocations that failed signature validation.
        /// When a revoke signature fails validation in `_handleRevokeLinkedSigner`, the attempted
        /// revocation is recorded here and marked as pending. The revocation remains pending until
        /// `finalizeRevokeLinkedSigner` is called.
        mapping(bytes32 subaccount => mapping(address signer => bool pending)) pendingSignerRevoke;
    }

    // --- Load --- //

    function load() internal pure returns (DataGlobal storage $) {
        bytes32 s = _SLOT_PATH;
        assembly {
            $.slot := s
        }
    }

    function load(address account) internal pure returns (Data storage $) {
        bytes32 s = keccak256(abi.encode("xyz.meridian.Account.Data", account));
        assembly {
            $.slot := s
        }
    }

    // --- Global --- //

    /// @dev Given an account address or signer address, return the associated account.
    function resolveAccount(DataGlobal storage self, address accountOrSigner) internal view returns (Data storage) {
        address accountAddress = self.linkedSignersToAccount[accountOrSigner];

        // 0x eq no linked signer, so it's an account (which or may or may not exist).
        if (accountAddress == address(0)) {
            return Account.load(accountOrSigner);
        }
        return Account.load(accountAddress);
    }

    /// @notice This function assumes signature validations have been performed externally.
    /// @dev Links a signer, marks nonce as used, and return true if success, false otherwise.
    function linkSigner(DataGlobal storage self, IActionHandler.LinkSignerMessage memory message, ActionId id)
        internal
        returns (bool)
    {
        Account.Data storage account = Account.load(message.sender);

        if (account.isNonceUsed(message.sender, ActionType.LinkSigner, message.nonce)) {
            revert InvalidNonce(id, message.nonce);
        }

        // Excluded addresses cannot be linked (e.g. subaccounts, system accounts).
        if (self.excludedSigners[message.signer]) {
            // Deposits automatically add `msg.sender` to an excluded signers mapping as accounts cannot be
            // used as a linked signer for another account. Here we verify that if the signer is an account then
            // flag `nonce` used and return false.
            //
            // However, if we are attempting to relink and previously revoked signer then throw a revert.
            if (Account.load(message.signer).sender != address(0)) {
                account.usedNonces[message.sender][ActionType.LinkSigner][message.nonce] = true;
                return false;
            }
            revert InvalidSigner(id, message.signer);
        }

        if (!account.isSubaccountRegistered(message.subaccount)) {
            revert SubaccountNotFound(id, message.sender, message.subaccount);
        }

        self.linkedSignersToAccount[message.signer] = message.sender;
        self.excludedSigners[message.signer] = true;

        account.linkedSigners[message.subaccount].add(message.signer);
        account.usedNonces[message.sender][ActionType.LinkSigner][message.nonce] = true;

        return true;
    }

    /// @notice Revokes a signer from a subaccount and marks the given nonce as used.
    /// @dev Once revoked the signer cannot be be relinked to another subaccount.
    function revokeSigner(DataGlobal storage self, IActionHandler.RevokeLinkedSignerMessage memory message, ActionId id)
        internal
    {
        Account.Data storage account = Account.load(message.sender);

        if (!account.isSubaccountRegistered(message.subaccount)) {
            revert SubaccountNotFound(id, message.sender, message.subaccount);
        }
        if (account.isNonceUsed(message.sender, ActionType.RevokeLinkedSigner, message.nonce)) {
            revert InvalidNonce(id, message.nonce);
        }
        if (!account.linkedSigners[message.subaccount].remove(message.signer)) {
            revert SignerNotFound(id, message.sender, message.subaccount, message.signer);
        }

        delete self.linkedSignersToAccount[message.signer];
        account.usedNonces[message.sender][ActionType.RevokeLinkedSigner][message.nonce] = true;
        self.excludedAccounts[message.signer] = true;
    }

    // --- Instance --- //

    /// @dev Returns true if subaccount has been registered, false otherwise.
    function isSubaccountRegistered(Data storage self, bytes32 subaccount) internal view returns (bool) {
        return self.hasRegistered[subaccount];
    }

    /// @dev Returns true if nonce has been used, false otherwise.
    function isNonceUsed(Data storage self, address sender, ActionType actionType, uint64 nonce)
        internal
        view
        returns (bool)
    {
        return self.usedNonces[sender][actionType][nonce];
    }

    /// @dev Updates the open positions by subaccount and quote token.
    function updateOpenPositions(Data storage self, bytes32 subaccount, address quoteToken, int128 delta) internal {
        self.openPositions[subaccount] = (self.openPositions[subaccount].toInt128() + delta).toUint256().toUint128();
        self.openPositionsByQuoteToken[subaccount][quoteToken] =
            (self.openPositionsByQuoteToken[subaccount][quoteToken].toInt128() + delta).toUint256().toUint128();
    }
}
"
    },
    "src/lib/storage/Exchange.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {ActionType} from "../../share/Enums.sol";
import {ActionExpired, NotSequencer, SequencerPaused} from "../../share/Errors.sol";
import {ActionId} from "../../share/UserDefinedTypes.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

library Exchange {
    bytes32 constant _SLOT_PATH = keccak256(abi.encode("xyz.meridian.Exchange.Data"));

    struct Data {
        /// Mapping of approved sequencers.
        mapping(address sequencer => bool approved) isSequencerApproved;
        /// Mapping of sequencers and their paused/unpaused status.
        mapping(address sequencer => bool paused) isSequencerPaused;
        /// Set of token names (virtual and concrete).
        EnumerableSet.Bytes32Set tokens;
        /// Mapping of token names by their concrete address.
        mapping(address token => bytes32 name) tokensByAddress;
        /// Time in seconds after the message signed at time, where the action is valid.
        mapping(ActionType action => uint64 buffer) actionExpiryBuffers;
        // Mapping of whether an address is approved to act as a delegate depositor.
        mapping(address delegateDepositor => bool approved) isDelegateDepositor;
        /// Whitelist of addresses that can control the pause state.
        mapping(address sender => bool hasPausePermission) isEmergencyPauser;
        /// Mapping of whether an address has been granted the claimer role.
        mapping(address claimer => bool approved) isClaimer;
        /// Address of the PythLazer contract for price verification.
        address pythLazer;
        /// Max Pyth price age tolerance (delta in seconds from `price.timestamp`).
        uint64 pythMaxAge;
        /// Last processed action identifier.
        ActionId lastActionId;
        /// The maximum number of deposits a delegate depositor may make in a batch.
        uint16 delegateDepositMaxBatchSize;
        /// Whether the exchange is currently paused.
        bool isPaused;
        /// Host chain LayerZero endpoint ID.
        uint32 lzEndpointId;
        /// Delay before a withdrawal can be rescued in seconds.
        uint64 rescueDelay;
        /// Last emitted ping timestamp.
        uint64 lastPingTimestamp;
    }

    function load() internal pure returns (Data storage $) {
        bytes32 s = _SLOT_PATH;
        assembly {
            $.slot := s
        }
    }

    /// @dev Returns true if `account` is sequencer and not paused.
    function isSequencer(Data storage self, address account) internal view returns (bool) {
        return self.isSequencerApproved[account] && !self.isSequencerPaused[account];
    }

    /// @dev Reverts if the `account` is not in the list of allowed sequencers, or if the sequencer is paused.
    function onlySequencer(Data storage self, address account) internal view {
        if (!self.isSequencerApproved[account]) {
            revert NotSequencer(account);
        }
        if (self.isSequencerPaused[account]) {
            revert SequencerPaused(account);
        }
    }

    /// @dev Reverts if the action is no longer valid for execution.
    function verifyBeforeActionExpiry(Data storage self, ActionId id, ActionType action, uint64 signedAt)
        internal
        view
    {
        if (block.timestamp > signedAt + self.actionExpiryBuffers[action]) {
            revert ActionExpired(id, block.timestamp, signedAt, self.actionExpiryBuffers[action]);
        }
    }
}
"
    },
    "src/lib/storage/FeeCollector.sol": {
      "content": "// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.28;

import {IExchangeGateway} from "../../interface/IExchangeGateway.sol";
import {Account} from "./Account.sol";

library FeeCollector {
    bytes32 constant _SLOT_PATH = keccak256(abi.encode("xyz.meridian.FeeCollector.Data"));

    struct Data {
        /// Exchange fess are accrued in the feeCollectorAccount
        address account;
        /// The subaccount identifier for the address accruing the protocol fees
        bytes32 subaccount;
    }

    function load() internal pure returns (Data storage $) {
        bytes32 s = _SLOT_PATH;
        assembly {
            $.slot := s
        }
    }

    /// @notice All fees from the protocol are awarded to the fee collector.
    function accrueFees(Data storage self, address feeToken, uint256 amount, uint64 messageIdx) internal {
        address account = self.account;
        bytes32 subaccount = self.subaccount;
        Account.Data storage accountData = Account.load(account);
        uint256 balance = accountData.balance[subaccount][feeToken] + amount;
        accountData.balance[subaccount][feeToken] = balance;

        emit IExchangeGateway.FeeAccrued(account, subaccount, feeToken, amount, balance, messageIdx);
    }
}
"
